text:
    stmt->BindInt64ByName("id"_ns, key);
    stmt->BindUTF8StringByName("tags"_ns, tags);
    rv = stmt->Execute();
    NS_ENSURE_SUCCESS(rv, rv);
  }

  // Update cache.
  auto p = mMsgCache.lookup(key);
  if (p) {
    p->value().tags = tags;
  }

  // TODO: notifications.
  return NS_OK;
